 120→export const action = async ({ request }: ActionFunctionArgs) => {
 121→  const { session, admin } = await authenticate.admin(request);
 122→  const shop = session.shop;
 123→  const formData = await request.formData();
 124→  const intent = formData.get("intent");
 125→
 126→  if (intent === "save") {
 127→    const data = {
 128→      position: String(formData.get("position") || "inline"),
 129→      primaryColor: String(formData.get("primaryColor") || "#008060"),
 130→      successColor: String(formData.get("successColor") || "#008060"),
 131→      errorColor: String(formData.get("errorColor") || "#D72C0D"),
 132→      backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
 133→      textColor: String(formData.get("textColor") || "#202223"),
 134→      heading: String(formData.get("heading") || "Check Delivery Availability"),
 135→      placeholder: String(formData.get("placeholder") || "Enter your zip code"),
 136→      buttonText: String(formData.get("buttonText") || "Check"),
 137→      successMessage: String(
 138→        formData.get("successMessage") ||
 139→          "Great news! We deliver to your area.",
 140→      ),
 141→      errorMessage: String(
 142→        formData.get("errorMessage") ||
 143→          "Sorry, we don't deliver to this area yet.",
 144→      ),
 145→      notFoundMessage: String(
 146→        formData.get("notFoundMessage") ||
 147→          "This zip code was not found in our system.",
 148→      ),
 149→      showEta: formData.get("showEta") === "true",
 150→      showZone: formData.get("showZone") === "true",
 151→      showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
 152→      borderRadius: String(formData.get("borderRadius") || "8"),
 153→      customCss: String(formData.get("customCss") || "") || null,
 154→    };
 155→
 156→    await db.widgetConfig.upsert({
 157→      where: { shop },
 158→      create: { shop, ...data },
 159→      update: data,
 160→    });
 161→
 162→    // Sync to shop metafield so storefront reads config without API call
 163→    await syncConfigMetafield(admin, data);
 164→
 165→    return { success: true };
 166→  }
 167→
 168→  if (intent === "reset") {
 169→    const resetData = {
 170→      position: "inline",
 171→      primaryColor: "#008060",
 172→      successColor: "#008060",
 173→      errorColor: "#D72C0D",
 174→      backgroundColor: "#FFFFFF",
 175→      textColor: "#202223",
 176→      heading: "Check Delivery Availability",
 177→      placeholder: "Enter your zip code",
 178→      buttonText: "Check",
 179→      successMessage: "Great news! We deliver to your area.",
 180→      errorMessage: "Sorry, we don't deliver to this area yet.",
 181→      notFoundMessage: "This zip code was not found in our system.",
 182→      showEta: true,
 183→      showZone: false,
 184→      showWaitlistOnFailure: false,
 185→      borderRadius: "8",
 186→      customCss: null,
 187→    };
 188→
 189→    await db.widgetConfig.upsert({
 190→      where: { shop },
 191→      create: { shop },
 192→      update: resetData,
 193→    });
 194→
 195→    // Sync reset config to metafield
 196→    await syncConfigMetafield(admin, resetData);
 197→
 198→    return { success: true, action: "reset" };
 199→  }
 200→
 201→  return null;
 202→};
