 224→// ── CSS generator — mirrors the Liquid block CSS exactly ────────────────────
 225→function buildWidgetCss(wid: string, cfg: WidgetConfig): string {
 226→  const rad = cfg.borderRadius + "px";
 227→  return (
 228→    "#" + wid + "{" +
 229→      "background:" + cfg.backgroundColor + ";" +
 230→      "color:" + cfg.textColor + ";" +
 231→      "border-radius:" + rad + ";" +
 232→      "padding:24px;" +
 233→      "border:1px solid #e1e3e5;" +
 234→      "max-width:400px;" +
 235→      "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;" +
 236→      "box-sizing:border-box;" +
 237→    "}" +
 238→    "#" + wid + " *{box-sizing:border-box}" +
 239→    "#" + wid + " .zcc-heading{font-size:16px;font-weight:600;margin:0 0 16px;color:" + cfg.textColor + "}" +
 240→    "#" + wid + " .zcc-row{display:flex;gap:8px;margin-bottom:0}" +
 241→    "#" + wid + " .zcc-input{" +
 242→      "flex:1;padding:10px 12px;border:1px solid #c9cccf;" +
 243→      "border-radius:" + rad + ";font-size:14px;outline:none;" +
 244→      "background:#fafbfb;color:" + cfg.textColor + ";min-width:0" +
 245→    "}" +
 246→    "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + ";box-shadow:0 0 0 2px " + cfg.primaryColor + "22}" +
 247→    "#" + wid + " .zcc-btn{" +
 248→      "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
 249→      "border-radius:" + rad + ";padding:10px 20px;font-size:14px;" +
 250→      "font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0" +
 251→    "}" +
 252→    "#" + wid + " .zcc-btn:hover{opacity:.9}" +
 253→    "#" + wid + " .zcc-result{margin-top:12px;padding:12px;border-radius:" + rad + ";font-size:14px;line-height:1.4}" +
 254→    "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15;border-left:3px solid " + cfg.successColor + ";color:" + cfg.successColor + "}" +
 255→    "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15;border-left:3px solid " + cfg.errorColor + ";color:" + cfg.errorColor + "}" +
 256→    "#" + wid + " .zcc-meta{margin-top:4px;font-size:13px;opacity:.8}" +
 257→    "#" + wid + " .zcc-wl{margin-top:10px}" +
 258→    "#" + wid + " .zcc-wl-input{" +
 259→      "width:100%;padding:8px 10px;border:1px solid " + cfg.errorColor + "40;" +
 260→      "border-radius:" + rad + ";font-size:13px;margin-bottom:6px;display:block" +
 261→    "}" +
 262→    "#" + wid + " .zcc-wl-btn{" +
 263→      "background:" + cfg.errorColor + ";color:#fff;border:none;" +
 264→      "border-radius:" + rad + ";padding:8px 16px;font-size:13px;" +
 265→      "cursor:pointer;width:100%;font-weight:600" +
 266→    "}" +
 267→    // Sanitize customCss: strip </style> close tags to prevent injection into <style> elements
 268→    (cfg.customCss ? cfg.customCss.replace(/<\/style>/gi, "") : "")
 269→  );
 270→}
