 272→// ── Live Preview component (defined outside WidgetPage to avoid remounting) ─
 273→function WidgetPreview({
 274→  cfg,
 275→  previewState,
 276→}: {
 277→  cfg: WidgetConfig;
 278→  previewState: "idle" | "success" | "error" | "notfound";
 279→}) {
 280→  const wid = "zcc-admin-preview";
 281→  const css = buildWidgetCss(wid, cfg);
 282→
 283→  const resultClass =
 284→    previewState === "success" ? "ok" :
 285→    (previewState === "error" || previewState === "notfound") ? "fail" : "";
 286→
 287→  const resultMessage =
 288→    previewState === "success" ? cfg.successMessage :
 289→    previewState === "error" ? cfg.errorMessage :
 290→    previewState === "notfound" ? cfg.notFoundMessage : null;
 291→
 292→  const widgetHtml = (
 293→    <div id={wid}>
 294→      <p className="zcc-heading">{cfg.heading}</p>
 295→      <div className="zcc-row">
 296→        <input
 297→          className="zcc-input"
 298→          type="text"
 299→          placeholder={cfg.placeholder}
 300→          readOnly
 301→        />
 302→        <button className="zcc-btn" type="button">
 303→          {cfg.buttonText}
 304→        </button>
 305→      </div>
 306→      {resultMessage && (
 307→        <div className={`zcc-result ${resultClass}`}>
 308→          {resultMessage}
 309→          {previewState === "success" && cfg.showEta && (
 310→            <div className="zcc-meta">Estimated delivery: 2–3 business days</div>
 311→          )}
 312→          {previewState === "success" && cfg.showZone && (
 313→            <div className="zcc-meta">Zone: Manhattan</div>
 314→          )}
 315→          {(previewState === "error" || previewState === "notfound") &&
 316→            cfg.showWaitlistOnFailure && (
 317→              <div className="zcc-wl">
 318→                <input
 319→                  className="zcc-wl-input"
 320→                  type="email"
 321→                  placeholder="Enter email to join waitlist"
 322→                  readOnly
 323→                />
 324→                <button className="zcc-wl-btn" type="button">
 325→                  Join Waitlist
 326→                </button>
 327→              </div>
 328→            )}
 329→        </div>
 330→      )}
 331→    </div>
 332→  );
 333→
 334→  // Floating position: show mock fixed button + collapsible panel concept
 335→  if (cfg.position === "floating") {
 336→    return (
 337→      <>
 338→        {/* eslint-disable-next-line react/no-danger */}
 339→        <style dangerouslySetInnerHTML={{ __html: css }} />
 340→        <div
 341→          style={{
 342→            position: "relative",
 343→            minHeight: "120px",
 344→            background: "#f6f6f7",
 345→            borderRadius: "8px",
 346→            padding: "12px",
 347→          }}
 348→        >
 349→          <Text as="p" variant="bodySm" tone="subdued">
 350→            The widget will appear as a fixed button in the bottom-right corner of your storefront.
 351→          </Text>
 352→          <div
 353→            style={{
 354→              position: "absolute",
 355→              bottom: "12px",
 356→              right: "12px",
 357→              display: "flex",
 358→              flexDirection: "column",
 359→              alignItems: "flex-end",
 360→              gap: "8px",
 361→            }}
 362→          >
 363→            <div id={wid} style={{ maxWidth: "300px" }}>
 364→              <p className="zcc-heading" style={{ marginBottom: "12px" }}>
 365→                {cfg.heading}
 366→              </p>
 367→              <div className="zcc-row">
 368→                <input
 369→                  className="zcc-input"
 370→                  type="text"
 371→                  placeholder={cfg.placeholder}
 372→                  readOnly
 373→                />
 374→                <button className="zcc-btn" type="button">
 375→                  {cfg.buttonText}
 376→                </button>
 377→              </div>
 378→            </div>
 379→            <button
 380→              type="button"
 381→              style={{
 382→                background: cfg.primaryColor,
 383→                color: "#fff",
 384→                border: "none",
 385→                borderRadius: "50px",
 386→                padding: "10px 18px",
 387→                fontSize: "13px",
 388→                fontWeight: 600,
 389→                cursor: "pointer",
 390→                boxShadow: "0 4px 12px rgba(0,0,0,.2)",
 391→              }}
 392→            >
 393→              📍 Check Delivery
 394→            </button>
 395→          </div>
 396→        </div>
 397→      </>
 398→    );
 399→  }
 400→
 401→  // Popup position: show trigger button + hint of overlay
 402→  if (cfg.position === "popup") {
 403→    return (
 404→      <>
 405→        {/* eslint-disable-next-line react/no-danger */}
 406→        <style dangerouslySetInnerHTML={{ __html: css }} />
 407→        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
 408→          <Text as="p" variant="bodySm" tone="subdued">
 409→            A trigger button will appear in the section. Clicking it opens a centered popup.
 410→          </Text>
 411→          <div>
 412→            <button
 413→              type="button"
 414→              style={{
 415→                background: cfg.primaryColor,
 416→                color: "#fff",
 417→                border: "none",
 418→                borderRadius: cfg.borderRadius + "px",
 419→                padding: "10px 24px",
 420→                fontSize: "14px",
 421→                fontWeight: 600,
 422→                cursor: "pointer",
 423→              }}
 424→            >
 425→              Check Delivery Availability
 426→            </button>
 427→          </div>
 428→          <div
 429→            style={{
 430→              background: "rgba(0,0,0,.06)",
 431→              borderRadius: "8px",
 432→              padding: "12px",
 433→              border: "2px dashed #c9cccf",
 434→            }}
 435→          >
 436→            <Text as="p" variant="bodySm" tone="subdued">
 437→              Popup content preview:
 438→            </Text>
 439→            <div style={{ marginTop: "8px" }}>{widgetHtml}</div>
 440→          </div>
 441→        </div>
 442→      </>
 443→    );
 444→  }
 445→
 446→  // Inline (default)
 447→  return (
 448→    <>
 449→      {/* eslint-disable-next-line react/no-danger */}
 450→      <style dangerouslySetInnerHTML={{ __html: css }} />
 451→      {widgetHtml}
 452→    </>
 453→  );
 454→}
