 456→// ── Page component ───────────────────────────────────────────────────────────
 457→export default function WidgetPage() {
 458→  const { config, themeEditorUrl } = useLoaderData<typeof loader>();
 459→  const fetcher = useFetcher<typeof action>();
 460→  const shopify = useAppBridge();
 461→  const navigate = useNavigate();
 462→
 463→  const c = config as WidgetConfig;
 464→
 465→  // Form state initialized from DB
 466→  const [position, setPosition] = useState(c.position);
 467→  const [primaryColor, setPrimaryColor] = useState(c.primaryColor);
 468→  const [successColor, setSuccessColor] = useState(c.successColor);
 469→  const [errorColor, setErrorColor] = useState(c.errorColor);
 470→  const [backgroundColor, setBackgroundColor] = useState(c.backgroundColor);
 471→  const [textColor, setTextColor] = useState(c.textColor);
 472→  const [heading, setHeading] = useState(c.heading);
 473→  const [placeholder, setPlaceholder] = useState(c.placeholder);
 474→  const [buttonText, setButtonText] = useState(c.buttonText);
 475→  const [successMessage, setSuccessMessage] = useState(c.successMessage);
 476→  const [errorMessage, setErrorMessage] = useState(c.errorMessage);
 477→  const [notFoundMessage, setNotFoundMessage] = useState(c.notFoundMessage);
 478→  const [showEta, setShowEta] = useState(c.showEta);
 479→  const [showZone, setShowZone] = useState(c.showZone);
 480→  const [showWaitlistOnFailure, setShowWaitlistOnFailure] = useState(
 481→    c.showWaitlistOnFailure,
 482→  );
 483→  const [borderRadius, setBorderRadius] = useState(c.borderRadius);
 484→  const [customCss, setCustomCss] = useState(c.customCss || "");
 485→
 486→  // Theme setup tracking (localStorage — no DB needed)
 487→  const [setupDone, setSetupDone] = useState(false);
 488→  useEffect(() => {
 489→    try {
 490→      setSetupDone(localStorage.getItem("zcc_theme_setup_done") === "true");
 491→    } catch {}
 492→  }, []);
 493→  const markSetupDone = useCallback(() => {
 494→    try {
 495→      localStorage.setItem("zcc_theme_setup_done", "true");
 496→    } catch {}
 497→    setSetupDone(true);
 498→  }, []);
 499→
 500→  // Unsaved changes tracking
 501→  const [isDirty, setIsDirty] = useState(false);
 502→
 503→  // Preview state
 504→  const [previewState, setPreviewState] = useState<
 505→    "idle" | "success" | "error" | "notfound"
 506→  >("idle");
 507→
 508→  const isSaving =
 509→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "save";
 510→
 511→  // Clear dirty flag after successful save
 512→  useEffect(() => {
 513→    if (
 514→      fetcher.state === "idle" &&
 515→      fetcher.data &&
 516→      "success" in fetcher.data &&
 517→      fetcher.data.success
 518→    ) {
 519→      setIsDirty(false);
 520→    }
 521→  }, [fetcher.state, fetcher.data]);
 522→
 523→  // Dirty-aware setters
 524→  const mark = useCallback(() => setIsDirty(true), []);
 525→  const handlePositionChange = useCallback((v: string) => { setPosition(v); mark(); }, [mark]);
 526→  const handlePrimaryColorChange = useCallback((v: string) => { setPrimaryColor(v); mark(); }, [mark]);
 527→  const handleSuccessColorChange = useCallback((v: string) => { setSuccessColor(v); mark(); }, [mark]);
 528→  const handleErrorColorChange = useCallback((v: string) => { setErrorColor(v); mark(); }, [mark]);
 529→  const handleBackgroundColorChange = useCallback((v: string) => { setBackgroundColor(v); mark(); }, [mark]);
 530→  const handleTextColorChange = useCallback((v: string) => { setTextColor(v); mark(); }, [mark]);
 531→  const handleHeadingChange = useCallback((v: string) => { setHeading(v); mark(); }, [mark]);
 532→  const handlePlaceholderChange = useCallback((v: string) => { setPlaceholder(v); mark(); }, [mark]);
 533→  const handleButtonTextChange = useCallback((v: string) => { setButtonText(v); mark(); }, [mark]);
 534→  const handleSuccessMessageChange = useCallback((v: string) => { setSuccessMessage(v); mark(); }, [mark]);
 535→  const handleErrorMessageChange = useCallback((v: string) => { setErrorMessage(v); mark(); }, [mark]);
 536→  const handleNotFoundMessageChange = useCallback((v: string) => { setNotFoundMessage(v); mark(); }, [mark]);
 537→  const handleShowEtaChange = useCallback((v: boolean) => { setShowEta(v); mark(); }, [mark]);
 538→  const handleShowZoneChange = useCallback((v: boolean) => { setShowZone(v); mark(); }, [mark]);
 539→  const handleShowWaitlistChange = useCallback((v: boolean) => { setShowWaitlistOnFailure(v); mark(); }, [mark]);
 540→  const handleBorderRadiusChange = useCallback((v: string) => { setBorderRadius(v); mark(); }, [mark]);
 541→  const handleCustomCssChange = useCallback((v: string) => { setCustomCss(v); mark(); }, [mark]);
 542→
 543→  const handleSave = useCallback(() => {
 544→    const fd = new FormData();
 545→    fd.set("intent", "save");
 546→    fd.set("position", position);
 547→    fd.set("primaryColor", primaryColor);
 548→    fd.set("successColor", successColor);
 549→    fd.set("errorColor", errorColor);
 550→    fd.set("backgroundColor", backgroundColor);
 551→    fd.set("textColor", textColor);
 552→    fd.set("heading", heading);
 553→    fd.set("placeholder", placeholder);
 554→    fd.set("buttonText", buttonText);
 555→    fd.set("successMessage", successMessage);
 556→    fd.set("errorMessage", errorMessage);
 557→    fd.set("notFoundMessage", notFoundMessage);
 558→    fd.set("showEta", String(showEta));
 559→    fd.set("showZone", String(showZone));
 560→    fd.set("showWaitlistOnFailure", String(showWaitlistOnFailure));
 561→    fd.set("borderRadius", borderRadius);
 562→    fd.set("customCss", customCss);
 563→    fetcher.submit(fd, { method: "POST" });
 564→    shopify.toast.show("Widget settings saved");
 565→  }, [
 566→    position, primaryColor, successColor, errorColor, backgroundColor,
 567→    textColor, heading, placeholder, buttonText, successMessage, errorMessage,
 568→    notFoundMessage, showEta, showZone, showWaitlistOnFailure, borderRadius,
 569→    customCss, fetcher, shopify,
 570→  ]);
 571→
 572→  const DEFAULTS = {
 573→    position: "inline",
 574→    primaryColor: "#008060",
 575→    successColor: "#008060",
 576→    errorColor: "#D72C0D",
 577→    backgroundColor: "#FFFFFF",
 578→    textColor: "#202223",
 579→    heading: "Check Delivery Availability",
